#[derive(Debug, PartialEq)]
pub enum Tecla {
    Enter,
    Volume,
    Brilho,
    Bloqueio,
}

pub fn o_rotulo_da(tecla: Tecla) -> String {
    match tecla {
        Tecla::Enter => String::from("processa"),
        _ => String::from("ignora"),
    }
}

testsCode:
use desafio::o_rotulo_da;
use desafio::Tecla;

#[test]
fn testa_o_rotulo_da_tecla_enter() {
    assert_eq!(o_rotulo_da(Tecla::Enter), String::from("processa"));
}

#[test]
fn testa_o_rotulo_da_tecla_volume() {
    assert_eq!(o_rotulo_da(Tecla::Volume), String::from("ignora"));
}

#[test]
fn testa_o_rotulo_da_tecla_bloqueio() {
    assert_eq!(o_rotulo_da(Tecla::Bloqueio), String::from("ignora"));
}
